<div class="card border-0 shadow-sm"><div class="card-body p-4"><h5>Staff Accounts</h5><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Name / Role</th><th>Campus</th><th>Assignment</th><th>Permissions</th><th>Actions</th></tr></thead><tbody>@forelse($users as $u)@php($perms=is_array($u->permissions)?$u->permissions:[])<tr><td><strong>{{$u->name}}</strong><br><small>{{$u->email}}</small><br><span class="badge bg-secondary">{{ucwords(str_replace('_',' ',$u->role))}}</span></td><td>{{$u->branch?->name?:'—'}}</td><td>{{$u->assigned_class?:'—'}} {{$u->assigned_section?'/ '.$u->assigned_section:''}}</td><td>{{collect($perms)->map(fn($p)=>$permissionLabels[$p]??$p)->implode(', ')?:'None'}}</td><td><details><summary class="btn btn-sm btn-outline-primary d-inline-block">Edit</summary><div class="mt-3 p-3 bg-light rounded" style="min-width:760px"><form method="POST" action="{{route('admin.staff-users.update',$u)}}" class="staff-user-form">@csrf @method('PUT')<div class="row g-3"><div class="col-md-3"><label>Name</label><input name="name" value="{{$u->name}}" class="form-control" required></div><div class="col-md-3"><label>Email</label><input type="email" name="email" value="{{$u->email}}" class="form-control" required></div><div class="col-md-3"><label>New Password</label><input type="password" name="password" class="form-control" placeholder="Leave blank"></div><div class="col-md-3"><label>Campus *</label><select name="branch_id" class="form-select staff-campus" required>@foreach($branches as $branch)<option value="{{$branch->id}}" @selected((string)$u->branch_id===(string)$branch->id)>{{$branch->name}}</option>@endforeach</select></div><div class="col-md-3"><label>Role</label><select name="role" class="form-select">@foreach(['class_teacher'=>'Class Teacher','office_manager'=>'Office Manager','principal'=>'Principal'] as $rv=>$rl)<option value="{{$rv}}" @selected($u->role===$rv)>{{$rl}}</option>@endforeach</select></div><div class="col-md-3"><l