<script>document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('.staff-user-form').forEach(form=>{const campus=form.querySelector('.staff-campus'),cls=form.querySelector('.staff-class'),section=form.querySelector('.staff-section');if(!campus||!cls||!section)return;const options=[...cls.options].map(o=>({value:o.value,text:o.textContent,branch:o.dataset.branch||'',sections:o.dataset.sections||'[]'}));function loadClasses(){const campusId=campus.value,current=cls.dataset.current||cls.value;cls.innerHTML='';options.forEach(o=>{if(!o.value||!o.branch||o.branch===campusId){const x=document.createElement('option');x.value=o.value;x.textContent=o.text;x.dataset.branch=o.branch;x.dataset.sections=o.sections;if(o.value===current)x.selected=true;cls.appendChild(x)}});if(![...cls.options].some(o=>o.selected))cls.selectedIndex=0;loadSections()}function loadSections(){const selected=cls.options[cls.selectedIndex],current=section.dataset.current||section.value;let list=[];try{list=JSON.parse(selected?.dataset?.sections||'[]')}catch(e){}section.innerHTML='<option value="">Not Applicable</option>';list.forEach(v=>{const x=document.createElement('option');x.value=v;x.textContent=v;if(v===current)x.selected=true;section.appendChild(x)})}campus.addEventListener('change',()=>{cls.dataset.current='';section.dataset.current='';loadClasses()});cls.addEventListener('change',()=>{section.dataset.current='';loadSections()});loadClasses()})});</script>
